/* Colour theme: LSU Health New Orleans purple and gold. */
/* GeoSENSE Lab: Research page, color-coded themes beside a zoomable world map of publications.
   Data comes from js/publications.js. Land shapes: Natural Earth (world-atlas), packed as bits.
   Zoom: mouse wheel, + / - buttons, double-click, or pinch. Drag to move around.              */
(function () {
  function initResearchMap() {
    const box = document.getElementById("pubmap");
    if (!box || !window.PUBS || box.dataset.ready) return false; // not loaded yet, or already built
    box.dataset.ready = "yes";
    const MAPS = {
      world: {
        land: {
          lon0: -180,
          lat1: 84,
          step: 1,
          W: 360,
          H: 144,
          bits: "",
        },
      },
      us: {
        land: {
          lon0: -140,
          lat1: 62,
          step: 0.3,
          W: 300,
          H: 167,
          bits: "",
        },
        focus: {
          lon0: -140,
          lat1: 62,
          step: 0.3,
          W: 300,
          H: 167,
          bits: "",
        },
      },
      bd: {
        land: {
          lon0: 72,
          lat1: 34,
          step: 0.12,
          W: 300,
          H: 183,
          bits: "",
        },
        focus: {
          lon0: 72,
          lat1: 34,
          step: 0.12,
          W: 300,
          H: 183,
          bits: "",
        },
      },
    };
    const THEMES = window.THEMES,
      PUBS = window.PUBS;
    const themeOf = (id) => THEMES.find((t) => t.id === id) || THEMES[0];
    const RAD = Math.PI / 180;
    const esc = (s) =>
      String(s).replace(
        /[&<>"]/g,
        (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c],
      );

    // ---- Land layers: coarse world, plus finer detail for the U.S. and Bangladesh when zoomed in ----
    const decode = (m) => {
      const s = atob(m.bits);
      return (k) => s.charCodeAt(k >> 3) & (1 << (k & 7));
    };
    const layer = (m, focus) => ({
      m,
      isLand: decode(m),
      isFocus: focus ? decode(focus) : null,
      lon1: m.lon0 + m.W * m.step,
      lat0: m.lat1 - m.H * m.step,
    });
    const WORLD = layer(MAPS.world.land);
    const DETAIL = [
      layer(MAPS.us.land, MAPS.us.focus),
      layer(MAPS.bd.land, MAPS.bd.focus),
    ];

    // ---- View state: map center and zoom ----
    const HOME = { lon: -15, lat: 14 },
      MAXZ = 16;
    let cx = HOME.lon,
      cy = HOME.lat,
      zoom = 1;
    const size = () => [box.clientWidth, box.clientHeight];
    function baseSpan() {
      const [w, h] = size();
      return Math.max(125, 250 / (w / h));
    } // whole study area fits at zoom 1
    function scale() {
      const [, h] = size();
      return h / (baseSpan() / zoom);
    } // pixels per degree of latitude
    const kx = () => Math.cos(Math.max(-60, Math.min(60, cy)) * RAD); // keeps shapes natural when zoomed
    function toPx(lon, lat) {
      const [w, h] = size(),
        s = scale();
      return [w / 2 + (lon - cx) * kx() * s, h / 2 - (lat - cy) * s];
    }
    function toLonLat(x, y) {
      const [w, h] = size(),
        s = scale();
      return [cx + (x - w / 2) / (kx() * s), cy - (y - h / 2) / s];
    }
    function clampView() {
      zoom = Math.max(1, Math.min(MAXZ, zoom));
      cx = Math.max(-170, Math.min(170, cx));
      cy = Math.max(-55, Math.min(78, cy));
      if (zoom === 1) {
        cx = HOME.lon;
        cy = HOME.lat;
      }
    }

    // ---- Drawing ----
    const canvas = box.querySelector("canvas"),
      ctx = canvas.getContext("2d");
    function drawLayer(L, clip, dim) {
      // a coarse cell that has grown large on screen is filled with several small dots, so all zoom levels share one texture
      const [w, h] = size(),
        s = scale(),
        m = L.m,
        cell = m.step * s * kx(),
        n = Math.max(1, Math.round(cell / 4.5));
      const sub = cell / n,
        dot = Math.min(4, Math.max(1.2, sub * 0.62)),
        cellY = m.step * s,
        subY = cellY / n;
      const [lonA, latB] = toLonLat(0, 0),
        [lonB, latA] = toLonLat(w, h);
      const i0 = Math.max(0, Math.floor((lonA - m.lon0) / m.step) - 1),
        i1 = Math.min(m.W - 1, Math.ceil((lonB - m.lon0) / m.step) + 1);
      const j0 = Math.max(0, Math.floor((m.lat1 - latB) / m.step) - 1),
        j1 = Math.min(m.H - 1, Math.ceil((m.lat1 - latA) / m.step) + 1);
      for (let j = j0; j <= j1; j++)
        for (let i = i0; i <= i1; i++) {
          const k = j * m.W + i;
          if (!L.isLand(k)) continue;
          const lon = m.lon0 + m.step * (i + 0.5),
            lat = m.lat1 - m.step * (j + 0.5);
          if (clip && clip(lon, lat)) continue;
          const [x, y] = toPx(lon, lat);
          ctx.fillStyle = L.isFocus
            ? L.isFocus(k)
              ? "rgba(186,168,212,.95)"
              : "rgba(186,168,212,.28)"
            : dim
              ? "rgba(186,168,212,.28)"
              : "rgba(186,168,212,.6)";
          if (n === 1) {
            ctx.fillRect(x - dot / 2, y - dot / 2, dot, dot);
            continue;
          }
          for (let a = 0; a < n; a++)
            for (let b = 0; b < n; b++)
              ctx.fillRect(
                x - cell / 2 + (a + 0.5) * sub - dot / 2,
                y - cellY / 2 + (b + 0.5) * subY - dot / 2,
                dot,
                dot,
              );
        }
    }
    function draw() {
      const [w, h] = size();
      if (!w) return;
      const dpr = window.devicePixelRatio || 1;
      if (canvas.width !== Math.round(w * dpr)) {
        canvas.width = w * dpr;
        canvas.height = h * dpr;
      }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.fillStyle = "#3C1053";
      ctx.fillRect(0, 0, w, h);
      // use a detailed layer once its dots are big enough to read
      const on = DETAIL.filter((L) => L.m.step * scale() * kx() >= 2.4);
      const inside = (lon, lat) =>
        on.some(
          (L) =>
            lon >= L.m.lon0 && lon < L.lon1 && lat >= L.lat0 && lat < L.m.lat1,
        );
      drawLayer(WORLD, on.length ? inside : null, on.length > 0); // match the dimmed neighbors once a detailed country is shown
      on.forEach((L) => drawLayer(L));
      placePins();
      zoomOut.disabled = zoom <= 1;
      zoomIn.disabled = zoom >= MAXZ;
    }

    // ---- Publication pins ----
    const pinLayer = box.querySelector(".pins"),
      pop = box.querySelector(".pop"),
      pins = [];
    PUBS.forEach((pub, n) =>
      pub.points.forEach(([lon, lat]) => {
        const b = document.createElement("button");
        b.className = "pin";
        b.type = "button";
        b.style.setProperty("--c", themeOf(pub.theme).color);
        b.setAttribute("aria-label", pub.title + ", " + pub.place);
        b.dataset.pub = n;
        b.dataset.theme = pub.theme;
        pinLayer.appendChild(b);
        pins.push({ b, lon, lat, pub });
      }),
    );
    function placePins() {
      const [w, h] = size();
      pins.forEach((p) => {
        const [x, y] = toPx(p.lon, p.lat);
        p.b.style.left = x + "px";
        p.b.style.top = y + "px";
        p.b.hidden = x < -8 || x > w + 8 || y < -8 || y > h + 8;
      });
    }

    // ---- Pop-up ----
    let hideTimer = null,
      pinned = null;
    function showPop(p) {
      clearTimeout(hideTimer);
      const t = themeOf(p.pub.theme),
        meta = [p.pub.journal, p.pub.year].filter(Boolean).join(", ");
      pop.innerHTML =
        '<span class="pop-theme" style="--c:' +
        t.color +
        '">' +
        esc(t.name) +
        "</span>" +
        "<h4>" +
        esc(p.pub.title) +
        "</h4>" +
        '<p class="pop-meta">' +
        esc(p.pub.place) +
        (meta ? "<br>" + esc(meta) : "") +
        "</p>" +
        (p.pub.figure
          ? '<img src="' +
            esc(p.pub.figure) +
            '" alt="Figure from ' +
            esc(p.pub.title) +
            '">'
          : "") +
        "<p>" +
        esc(p.pub.summary) +
        "</p>" +
        (p.pub.link
          ? '<a href="' +
            esc(p.pub.link) +
            '" target="_blank" rel="noopener">Read the paper</a>'
          : "");
      pop.hidden = false;
      const [w] = size(),
        x = p.b.offsetLeft,
        y = p.b.offsetTop,
        pw = pop.offsetWidth;
      pop.style.left =
        (x + 16 + pw < w ? x + 16 : Math.max(0, x - 16 - pw)) + "px";
      pop.style.top = Math.max(0, y - 24) + "px";
    }
    function hidePop(now) {
      if (pinned) return;
      clearTimeout(hideTimer);
      hideTimer = setTimeout(() => (pop.hidden = true), now ? 0 : 200);
    }
    function closePop() {
      pinned = null;
      pop.hidden = true;
    }
    pins.forEach((p) => {
      p.b.addEventListener("mouseenter", () => {
        if (!dragging) showPop(p);
      });
      p.b.addEventListener("mouseleave", () => hidePop());
      p.b.addEventListener("focus", () => showPop(p));
      p.b.addEventListener("blur", () => hidePop());
      p.b.addEventListener("click", (e) => {
        if (moved) return;
        pinned = pinned === p ? null : p;
        showPop(p);
      }); // tap keeps it open
    });
    pop.addEventListener("mouseenter", () => clearTimeout(hideTimer));
    pop.addEventListener("mouseleave", () => hidePop());
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape") closePop();
    });
    document.addEventListener("click", (e) => {
      if (pinned && !box.contains(e.target)) closePop();
    });

    // ---- Zoom and pan ----
    let anim = null;
    function zoomAt(factor, px, py, smooth) {
      // keep the point under (px, py) fixed
      const [w, h] = size();
      px = px ?? w / 2;
      py = py ?? h / 2;
      const [lon, lat] = toLonLat(px, py),
        z0 = zoom,
        c0 = [cx, cy];
      const z1 = Math.max(1, Math.min(MAXZ, zoom * factor));
      const target = () => {
        zoom = z1;
        const [lon2, lat2] = toLonLat(px, py);
        const t = [cx + lon - lon2, cy + lat - lat2];
        return t;
      };
      zoom = z1;
      cx = c0[0];
      cy = c0[1];
      const [tx, ty] = target();
      zoom = z0;
      closePop();
      cancelAnimationFrame(anim);
      if (!smooth) {
        zoom = z1;
        cx = tx;
        cy = ty;
        clampView();
        draw();
        return;
      }
      const start = performance.now();
      (function step(now) {
        const q = Math.min(1, (now - start) / 250),
          e = 1 - (1 - q) ** 3;
        zoom = z0 * Math.pow(z1 / z0, e);
        cx = c0[0] + (tx - c0[0]) * e;
        cy = c0[1] + (ty - c0[1]) * e;
        clampView();
        draw();
        if (q < 1) anim = requestAnimationFrame(step);
      })(start);
    }
    const zoomIn = box.querySelector(".zoom-in"),
      zoomOut = box.querySelector(".zoom-out"),
      zoomReset = box.querySelector(".zoom-reset");
    zoomIn.addEventListener("click", () => zoomAt(2, null, null, true));
    zoomOut.addEventListener("click", () => zoomAt(0.5, null, null, true));
    zoomReset.addEventListener("click", () =>
      zoomAt(1 / zoom, null, null, true),
    );
    box.addEventListener("dblclick", (e) => {
      if (e.target.closest(".pin, .pop, .zoom")) return;
      const r = box.getBoundingClientRect();
      zoomAt(2, e.clientX - r.left, e.clientY - r.top, true);
    });

    // mouse wheel zooms around the pointer; at the zoom limits the page scrolls as usual
    box.addEventListener(
      "wheel",
      (e) => {
        if ((e.deltaY > 0 && zoom <= 1) || (e.deltaY < 0 && zoom >= MAXZ))
          return;
        e.preventDefault();
        const r = box.getBoundingClientRect();
        zoomAt(
          Math.exp(-e.deltaY * 0.0025),
          e.clientX - r.left,
          e.clientY - r.top,
          false,
        );
      },
      { passive: false },
    );

    // drag to pan; two fingers to pinch-zoom
    const pts = new Map();
    let dragging = false,
      moved = false,
      last = null,
      pinch = null;
    box.addEventListener("pointerdown", (e) => {
      if (e.target.closest(".pop, .zoom")) return;
      pts.set(e.pointerId, [e.clientX, e.clientY]);
      moved = false;
      if (pts.size === 1) {
        dragging = true;
        last = [e.clientX, e.clientY];
      }
      if (pts.size === 2) {
        const [a, b] = [...pts.values()];
        pinch = { d: Math.hypot(a[0] - b[0], a[1] - b[1]), z: zoom };
      }
    });
    addEventListener("pointermove", (e) => {
      if (!pts.has(e.pointerId)) return;
      pts.set(e.pointerId, [e.clientX, e.clientY]);
      const r = box.getBoundingClientRect();
      if (pts.size === 2 && pinch) {
        const [a, b] = [...pts.values()],
          d = Math.hypot(a[0] - b[0], a[1] - b[1]);
        zoomAt(
          (pinch.z * d) / pinch.d / zoom,
          (a[0] + b[0]) / 2 - r.left,
          (a[1] + b[1]) / 2 - r.top,
          false,
        );
        moved = true;
        return;
      }
      if (!dragging || zoom <= 1) return;
      const dx = e.clientX - last[0],
        dy = e.clientY - last[1];
      if (Math.abs(dx) + Math.abs(dy) > 2) {
        moved = true;
        box.classList.add("grabbing");
        closePop();
      }
      last = [e.clientX, e.clientY];
      const s = scale();
      cx -= dx / (kx() * s);
      cy += dy / s;
      clampView();
      draw();
    });
    const end = (e) => {
      pts.delete(e.pointerId);
      if (pts.size < 2) pinch = null;
      if (!pts.size) {
        dragging = false;
        box.classList.remove("grabbing");
        setTimeout(() => (moved = false), 0);
      }
    };
    addEventListener("pointerup", end);
    addEventListener("pointercancel", end);

    // ---- Theme list (left column): hover to preview, click to filter ----
    const list = document.getElementById("theme-list");
    THEMES.forEach((t) => {
      const count = PUBS.filter((p) => p.theme === t.id).length;
      const li = document.createElement("li");
      li.innerHTML =
        '<button type="button" class="theme" data-theme="' +
        t.id +
        '" style="--c:' +
        t.color +
        '" aria-pressed="false">' +
        '<span class="dot" aria-hidden="true"></span><span class="tname">' +
        esc(t.name) +
        "</span>" +
        '<span class="tcount">' +
        count +
        (count === 1 ? " publication" : " publications") +
        "</span>" +
        '<span class="ttext">' +
        esc(t.text) +
        "</span></button>";
      list.appendChild(li);
    });
    let active = null,
      hoverTheme = null;
    const themeBtns = [...list.querySelectorAll(".theme")];
    function styleThemes() {
      const show = hoverTheme || active;
      pins.forEach((p) =>
        p.b.classList.toggle("dim", !!show && p.pub.theme !== show),
      );
      themeBtns.forEach((b) => {
        const on = active === b.dataset.theme;
        b.classList.toggle("on", on);
        b.setAttribute("aria-pressed", on);
      });
    }
    themeBtns.forEach((b) => {
      b.addEventListener("mouseenter", () => {
        hoverTheme = b.dataset.theme;
        styleThemes();
      });
      b.addEventListener("mouseleave", () => {
        hoverTheme = null;
        styleThemes();
      });
      b.addEventListener("click", () => {
        active = active === b.dataset.theme ? null : b.dataset.theme;
        styleThemes();
      });
    });

    addEventListener("resize", () => {
      clampView();
      draw();
    });
    addEventListener("hashchange", () => setTimeout(draw, 0)); // the Research tab may have been hidden
    draw();
    return true;
  }
  // Research lives in pages/research.html: build the map now if it's already on the page,
  // otherwise as soon as main.js finishes loading it.
  if (!initResearchMap())
    addEventListener("page:loaded", (e) => {
      if (e.detail && e.detail.id === "page-research") initResearchMap();
    });
})();
